    override fun read(buf: ByteBuffer): PublishOptions {
        return PublishOptions(
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterBoolean.read(buf),
            FfiConverterTypeMessageProperties.read(buf),
            FfiConverterOptionalString.read(buf),
        )
    }

    override fun allocationSize(value: PublishOptions) = (
            FfiConverterBoolean.allocationSize(value.`persistent`) +
            FfiConverterBoolean.allocationSize(value.`mandatory`) +
            FfiConverterBoolean.allocationSize(value.`confirm`) +
            FfiConverterTypeMessageProperties.allocationSize(value.`properties`) +
            FfiConverterOptionalString.allocationSize(value.`headersJson`)
    )

    override fun write(value: PublishOptions, buf: ByteBuffer) {
            FfiConverterBoolean.write(value.`persistent`, buf)
            FfiConverterBoolean.write(value.`mandatory`, buf)
            FfiConverterBoolean.write(value.`confirm`, buf)
            FfiConverterTypeMessageProperties.write(value.`properties`, buf)
            FfiConverterOptionalString.write(value.`headersJson`, buf)
    }
}



