/**
 * Errors returned by every binding call.
 */
sealed class FireMqException: kotlin.Exception() {
    
    /**
     * The broker refused a request. `code` is an AMQP reply code such as 403, 404 or 406.
     */
    class Server(
        
        val `code`: kotlin.UShort, 
        
        val `reason`: kotlin.String
        ) : FireMqException() {
        override val message
            get() = "code=${ `code` }, reason=${ `reason` }"
    }
    
    /**
     * A mandatory publish matched no queue.
     */
    class Unroutable(
        
        val `reason`: kotlin.String
        ) : FireMqException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * The broker rejected a publish, for example because a queue was full.
     */
    class Nacked(
        
        val `code`: kotlin.UShort, 
        
        val `reason`: kotlin.String
        ) : FireMqException() {
        override val message
            get() = "code=${ `code` }, reason=${ `reason` }"
    }
    
    /**
     * The connection or subscription is closed.
     */
    class Closed(
        
        val `reason`: kotlin.String
        ) : FireMqException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    
    /**
     * Anything else: I/O failures, invalid URLs or JSON, protocol errors.
     */
    class Other(
        
        val `reason`: kotlin.String
        ) : FireMqException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FireMqException> {
        override fun lift(error_buf: RustBuffer.ByValue): FireMqException = FfiConverterTypeFireMqError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFireMqError : FfiConverterRustBuffer<FireMqException> {
    override fun read(buf: ByteBuffer): FireMqException {
        

        return when(buf.getInt()) {
            1 -> FireMqException.Server(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                )
            2 -> FireMqException.Unroutable(
                FfiConverterString.read(buf),
                )
            3 -> FireMqException.Nacked(
                FfiConverterUShort.read(buf),
                FfiConverterString.read(buf),
                )
            4 -> FireMqException.Closed(
                FfiConverterString.read(buf),
                )
            5 -> FireMqException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FireMqException): ULong {
        return when(value) {
            is FireMqException.Server -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FireMqException.Unroutable -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FireMqException.Nacked -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterUShort.allocationSize(value.`code`)
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FireMqException.Closed -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
            is FireMqException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: FireMqException, buf: ByteBuffer) {
        when(value) {
            is FireMqException.Server -> {
                buf.putInt(1)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FireMqException.Unroutable -> {
                buf.putInt(2)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FireMqException.Nacked -> {
                buf.putInt(3)
                FfiConverterUShort.write(value.`code`, buf)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FireMqException.Closed -> {
                buf.putInt(4)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
            is FireMqException.Other -> {
                buf.putInt(5)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalUByte: FfiConverterRustBuffer<kotlin.UByte?> {
    override fun read(buf: ByteBuffer): kotlin.UByte? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterUByte.read(buf)
    }

    override fun allocationSize(value: kotlin.UByte?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterUByte.allocationSize(value)
        }
    }

    override fun write(value: kotlin.UByte?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterUByte.write(value, buf)
        }
    }
}




